From e7cd9a5f58a0422cb5d7d34994339fa15dbbef18 Mon Sep 17 00:00:00 2001
From: Alexander Hohenhorst <alexander.hohenhorst@gmx.de>
Date: Thu, 5 Nov 2026 00:44:19 +0100
Subject: [PATCH 1/2] lockscreen: don't drop passwords submitted while no
 prompt is pending

The greeter drops a response that arrives while no PAM prompt is
pending ("Received prompt response, but no pending prompt was found!")
without telling the user. This happens when the password is submitted
before the worker is ready (e.g. right after waking from suspend) or
during the fail delay after a wrong password.

The code that was meant to hold the password in that case checks
authenticator.pamTimeout, which does not exist; kscreenlocker calls it
inPasswordDelay, and PamAuthenticators never emits inPasswordDelayChanged
either. So the password was always sent immediately and dropped.

In addition, startLogin() moves focus to the unlock button and the field
is only cleared once the failure arrives. Keys typed in the meantime are
lost and pressing Enter submits the previous password again; retyping
after a dropped submit appends to the old text. Each such attempt counts
as a failed login, which can trip pam_faillock with the correct password.

Track whether a secret prompt is pending, hold a submitted password until
the next prompt arrives (responding from the event loop, since the
greeter stores the pending prompt only after emitting the signal), and
clear and refocus the field on submit. A timer re-enables the field if no
prompt shows up.
---
 .../contents/lockscreen/LockScreenUi.qml      | 65 ++++++++++++++-----
 1 file changed, 49 insertions(+), 16 deletions(-)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index 065a33c131..e1b6f34a8b 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -52,6 +52,34 @@ Item {
     }

     property string pendingPassword
+    // Whether the authenticator is currently waiting for a secret. A response sent while
+    // no prompt is pending is dropped by the greeter, so passwords submitted at such a
+    // time (before the worker is ready, or during the fail delay) are held until the
+    // next prompt arrives.
+    property bool secretPromptPending: false
+
+    function flushPendingPassword(): void {
+        if (secretPromptPending && pendingPassword.length > 0) {
+            const password = pendingPassword;
+            pendingPassword = "";
+            secretPromptPending = false;
+            pendingPasswordTimeout.stop();
+            mainBlock.enabled = true;
+            mainBlock.mainPasswordBox.forceActiveFocus();
+            authenticator.respond(password);
+        }
+    }
+
+    Timer {
+        id: pendingPasswordTimeout
+        // Never leave the password field disabled if no prompt shows up.
+        interval: 8000
+        onTriggered: {
+            lockScreenUi.pendingPassword = "";
+            mainBlock.enabled = true;
+            root.clearPassword();
+        }
+    }

     Kirigami.Theme.inherit: false
     Kirigami.Theme.colorSet: Kirigami.Theme.Complementary
@@ -64,7 +92,9 @@ Item {
             }
             const msg = i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Unlocking failed");
             lockScreenUi.handleMessage(msg);
-            root.clearPassword();
+            // The field was already cleared on submit; don't wipe a retry that is being typed.
+            mainBlock.mainPasswordBox.forceActiveFocus();
+            lockScreenUi.secretPromptPending = false;
             authenticator.startAuthenticating();
             notificationRemoveTimer.restart();
             rejectPasswordAnimation.start();
@@ -104,6 +134,12 @@ Item {
         function onPromptForSecretChanged() {
             mainBlock.showPassword = false;
             mainBlock.mainPasswordBox.forceActiveFocus();
+            if (authenticator.promptForSecret !== "" && !authenticator.busy) {
+                lockScreenUi.secretPromptPending = true;
+                // The greeter only stores the pending prompt after emitting this signal,
+                // so respond from the event loop rather than from within the handler.
+                Qt.callLater(lockScreenUi.flushPendingPassword);
+            }
             if (lockScreenUi.showPrompt) {
                 lockScreenUi.handleMessage(authenticator.promptForSecret);
             }
@@ -287,16 +323,6 @@ Item {
             }
         }

-        Connections {
-            target: authenticator
-            function onPamTimeoutChanged(): void {
-                if (!authenticator.pamTimeout && lockScreenUi.pendingPassword.length > 0) {
-                    authenticator.respond(lockScreenUi.pendingPassword);
-                    lockScreenUi.pendingPassword = "";
-                    mainBlock.enabled = true;
-                }
-            }
-        }

         StackView {
             id: mainStack
@@ -397,11 +423,18 @@ Item {
                 }

                 onPasswordResult: password => {
-                    if (authenticator.pamTimeout) {
-                        lockScreenUi.pendingPassword = password
-                        mainBlock.enabled = false
-                    } else {
-                        authenticator.respond(password)
+                    // Clear and refocus the field right away. Otherwise focus stays on the
+                    // unlock button until the result arrives: keys typed in the meantime are
+                    // lost and pressing Enter submits the previous password again.
+                    root.clearPassword();
+                    if (lockScreenUi.secretPromptPending) {
+                        lockScreenUi.secretPromptPending = false;
+                        authenticator.respond(password);
+                    } else if (password.length > 0) {
+                        lockScreenUi.pendingPassword = password;
+                        mainBlock.enabled = false;
+                        pendingPasswordTimeout.restart();
+                        authenticator.startAuthenticating();
                     }
                 }

-- 
