From 12f20202713c6e600b99062626dd247f6e53aa2d Mon Sep 17 00:00:00 2001
From: Alexander Hohenhorst <alexander.hohenhorst@gmx.de>
Date: Thu, 5 Nov 2026 00:44:29 +0100
Subject: [PATCH 2/2] lockscreen: don't treat Enter on an empty field as an
 unlock attempt

Pressing Enter on the empty password field, e.g. to wake the screen,
sends an empty password to PAM. With nullok in the stack that is a real
authentication failure and counts towards pam_faillock, so waking the
lock screen this way can use up attempts before typing anything.

Ignore empty submissions.

BUG: 528356
---
 desktoppackage/contents/lockscreen/LockScreenUi.qml | 7 ++++++-
 1 file changed, 6 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index e1b6f34a8b..8f35d454db 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -427,10 +427,15 @@ Item {
                     // unlock button until the result arrives: keys typed in the meantime are
                     // lost and pressing Enter submits the previous password again.
                     root.clearPassword();
+                    if (password.length === 0) {
+                        // Pressing Enter on an empty field, e.g. to wake the screen, is not
+                        // an unlock attempt. PAM would count it as a failed login.
+                        return;
+                    }
                     if (lockScreenUi.secretPromptPending) {
                         lockScreenUi.secretPromptPending = false;
                         authenticator.respond(password);
-                    } else if (password.length > 0) {
+                    } else {
                         lockScreenUi.pendingPassword = password;
                         mainBlock.enabled = false;
